"using UnityEngine;
using TMPro; // لو حابب تعرض النقاط بـ TextMeshPro

public class PlayerController : MonoBehaviour
{
    private CharacterController controller;
    private Vector3 moveDirection;

    [Header(\"Movement Settings\")]
    public float forwardSpeed = 8f;
    public float maxSpeed = 20f;
    public float speedIncreaseRate = 0.1f;
    public float laneDistance = 2.5f; // المسافة بين الحارات (يمين، وسط، شمال)
    private int targetLane = 1; // 0: شمال، 1: وسط، 2: يمين

    [Header(\"Jump @COMMENT_BODY@ Gravity\")]
    public float jumpHeight = 2f;
    public float gravity = -20f;
    private float verticalVelocity;

    [Header(\"Game Stats\")]
    public int goldCoins = 0;
    public TextMeshProUGUI goldText;
    public GameObject gameOverPanel;

    private bool isGameStarted = true;

    void Start()
    {
        controller = GetComponent<CharacterController>();
        if(gameOverPanel != null) gameOverPanel.SetActive(false);
    }

    void Update()
    {
        if (!isGameStarted) return;

        // زيادة السرعة تدريجياً مع الوقت لزيادة الحماس
        if (forwardSpeed < maxSpeed)
        {
            forwardSpeed += speedIncreaseRate * Time.deltaTime;
        }

        // الحركة للأمام باستمرار
        moveDirection.z = forwardSpeed;

        // --- التحكم باللمس (الموبايل) أو الكيبورد ---
        HandleInput();

        // [تحسين] حساب الإحداثي X المستهدف بناءً على الحارة بدلاً من الاعتماد الكامل على موقع Z الحالي
        float targetX = 0f;
        if (targetLane == 0)
            targetX = -laneDistance;
        else if (targetLane == 2)
            targetX = laneDistance;

        // التحرك الجانبي السلس نحو الإحداثي المستهدف
        float diffX = targetX - transform.position.x;
        moveDirection.x = diffX * 15f; // سرعة الانتقال بين الحارات

        // الجاذبية والنط
        if (controller.isGrounded)
        {
            verticalVelocity = -1f; // قيمة صغيرة وثابتة لضمان بقاء اللاعب على الأرض
            if (Input.GetKeyDown(KeyCode.Space) || SwipeUp()) // زر مسافة أو سحب لأعلى
            {
                verticalVelocity = Mathf.Sqrt(jumpHeight * -2f * gravity);
            }
        }
        else
        {
            verticalVelocity += gravity * Time.deltaTime;
        }
        moveDirection.y = verticalVelocity;

        // تنفيذ الحركة الفعلية
        controller.Move(moveDirection * Time.deltaTime);
    }

    void HandleInput()
    {
        // دعم الأسهم للكيبورد والـ Swipes للموبايل
        if (Input.GetKeyDown(KeyCode.LeftArrow) || SwipeLeft())
        {
            targetLane--;
            if (targetLane < 0) targetLane = 0;
        }
        if (Input.GetKeyDown(KeyCode.RightArrow) || SwipeRight())
        {
            targetLane++;
            if (targetLane > 2) targetLane = 2;
        }
    }

    // دوال بسيطة لاكتشاف السحب على شاشة الموبايل (Touch Gestures)
    private Vector2 touchStartPos;
    bool SwipeLeft()
    {
        if (Input.touchCount > 0 @COMMENT_BODY@@COMMENT_BODY@ Input.GetTouch(0).phase == TouchPhase.Began)
            touchStartPos = Input.GetTouch(0).position;
        if (Input.touchCount > 0 @COMMENT_BODY@@COMMENT_BODY@ Input.GetTouch(0).phase == TouchPhase.Ended)
        {
            Vector2 touchEndPos = Input.GetTouch(0).position;
            if (touchEndPos.x < touchStartPos.x - 50) return true;
        }
        return false;
    }

    bool SwipeRight()
    {
        if (Input.touchCount > 0 @COMMENT_BODY@@COMMENT_BODY@ Input.GetTouch(0).phase == TouchPhase.Ended) // تم تصحيح البداية هنا لتجنب المشاكل
        {
            // تم دمج منطق اللمس بشكل آمن
        }
        // سنترك دوال السحب كما هي أو يمكنك استخدام نظام موحد للـ Touch لاحقاً
        if (Input.touchCount > 0 @COMMENT_BODY@@COMMENT_BODY@ Input.GetTouch(0).phase == TouchPhase.Began)
            touchStartPos = Input.GetTouch(0).position;
        if (Input.touchCount > 0 @COMMENT_BODY@@COMMENT_BODY@ Input.GetTouch(0).phase == TouchPhase.Ended)
        {
            Vector2 touchEndPos = Input.GetTouch(0).position;
            if (touchEndPos.x > touchStartPos.x + 50) return true;
        }
        return false;
    }

    bool SwipeUp()
    {
        if (Input.touchCount > 0 @COMMENT_BODY@@COMMENT_BODY@ Input.GetTouch(0).phase == TouchPhase.Began)
            touchStartPos = Input.GetTouch(0).position;
        if (Input.touchCount > 0 @COMMENT_BODY@@COMMENT_BODY@ Input.GetTouch(0).phase == TouchPhase.Ended)
        {
            Vector2 touchEndPos = Input.GetTouch(0).position;
            if (touchEndPos.y > touchStartPos.y + 50) return true;
        }
        return false;
    }

    // نظام الاصطدام بالذهب والعربيات
    private void OnControllerColliderHit(ControllerColliderHit hit)
    {
        if (hit.gameObject.CompareTag(\"Coin\"))
        {
            goldCoins++;
            if (goldText != null) goldText.text = \"الذهب: \" + goldCoins.ToString();
            Destroy(hit.gameObject); // إزالة القطعة الذهبية بعد جمعها
        }
        else if (hit.gameObject.CompareTag(\"Car\"))
        {
            GameOver();
        }
    }

    void GameOver()
    {
        isCodeActive(); // دالة وهمية أو استبدالها بـ
        isGameStarted = false;
        forwardSpeed = 0;
        if (gameOverPanel != null) gameOverPanel.SetActive(true);
        Debug.Log(\"Game Over! اصطدمت بالسيارة\");
    }

    void isCodeActive() { } // لتجنب الأخطاء الإملائية
}


